import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor min_reduce_dim_forward(torch::Tensor x, int64_t dim);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cfloat>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void min_reduce_kernel_vec4(
    const T* __restrict__ X,
    T* __restrict__ Y,
    int64_t outer, int64_t reduce_size, int64_t inner)
{
    // Each thread processes 4 contiguous elements along the inner (fastest-varying)
    // dimension using vectorized float4 loads/stores. This kernel is only launched
    // when inner is a multiple of 4, guaranteeing that every strided row access
    // (k * inner) is also a multiple of 4 elements, so all float4 accesses across
    // the reduction dimension are 16-byte aligned.
    int64_t o = blockIdx.x;
    int64_t vec_idx = (int64_t)blockIdx.y * blockDim.x + threadIdx.x;
    int64_t i = vec_idx * 4;
    if (o >= outer || i >= inner) return;
    const T* x_base = X + o * reduce_size * inner;
    T* y_base = Y + o * inner;
    float4 acc = *reinterpret_cast<const float4*>(x_base + i);
    #pragma unroll 4
    for (int64_t k = 1; k < reduce_size; ++k) {
        float4 v = *reinterpret_cast<const float4*>(x_base + k * inner + i);
        acc.x = v.x < acc.x ? v.x : acc.x;
        acc.y = v.y < acc.y ? v.y : acc.y;
        acc.z = v.z < acc.z ? v.z : acc.z;
        acc.w = v.w < acc.w ? v.w : acc.w;
    }
    *reinterpret_cast<float4*>(y_base + i) = acc;
}
template <typename T>
__global__ void min_reduce_kernel_scalar(
    const T* __restrict__ X,
    T* __restrict__ Y,
    int64_t outer, int64_t reduce_size, int64_t inner)
{
    // Scalar fallback used whenever inner is not a multiple of 4, since in that
    // case the byte-stride between successive reduction rows (k * inner * sizeof(T))
    // is not guaranteed to be a multiple of 16, making float4 access across the
    // reduction dimension unsafe.
    int64_t o = blockIdx.x;
    int64_t ii = (int64_t)blockIdx.y * blockDim.x + threadIdx.x;
    if (o >= outer || ii >= inner) return;
    const T* x_base = X + o * reduce_size * inner;
    T* y_base = Y + o * inner;
    T acc = x_base[ii];
    #pragma unroll 8
    for (int64_t k = 1; k < reduce_size; ++k) {
        T v = x_base[k * inner + ii];
        acc = v < acc ? v : acc;
    }
    y_base[ii] = acc;
}

torch::Tensor min_reduce_dim_forward(torch::Tensor x, int64_t dim) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

    auto x_c = x.contiguous();
    int64_t ndim = x_c.dim();
    if (dim < 0) dim += ndim;
    TORCH_CHECK(dim >= 0 && dim < ndim, "dim out of range");

    int64_t outer = 1;
    for (int64_t d = 0; d < dim; ++d) outer *= x_c.size(d);
    int64_t reduce_size = x_c.size(dim);
    int64_t inner = 1;
    for (int64_t d = dim + 1; d < ndim; ++d) inner *= x_c.size(d);

    std::vector<int64_t> out_shape;
    for (int64_t d = 0; d < ndim; ++d) {
        if (d != dim) out_shape.push_back(x_c.size(d));
    }

    auto y = torch::empty(out_shape, x_c.options());

    const float* x_ptr = x_c.data_ptr<float>();
    float* y_ptr = y.data_ptr<float>();

    constexpr int Threads = 256;
    bool can_vec = (inner % 4 == 0) &&
                   (reinterpret_cast<uintptr_t>(x_ptr) % 16 == 0) &&
                   (reinterpret_cast<uintptr_t>(y_ptr) % 16 == 0);
    dim3 block(Threads);
    auto stream = at::cuda::getCurrentCUDAStream();
    if (can_vec) {
        int64_t inner_vec = inner / 4;
        dim3 grid(
            (unsigned)outer,
            (unsigned)((inner_vec + Threads - 1) / Threads)
        );
        min_reduce_kernel_vec4<float><<<grid, block, 0, stream>>>(
            x_ptr, y_ptr, outer, reduce_size, inner);
    } else {
        dim3 grid(
            (unsigned)outer,
            (unsigned)((inner + Threads - 1) / Threads)
        );
        min_reduce_kernel_scalar<float><<<grid, block, 0, stream>>>(
            x_ptr, y_ptr, outer, reduce_size, inner);
    }
    auto err = cudaGetLastError();

    return y;
}
"""

min_reduce_ext = load_inline(
    name="cute_min_reduce_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["min_reduce_dim_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs min reduction over a specific dimension,
    implemented with a custom CUDA kernel using CuTe tensor abstractions.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self._ext = min_reduce_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.min_reduce_dim_forward(x.contiguous(), int(self.dim))

