#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cfloat>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void min_reduce_kernel(
    const T* __restrict__ X,
    T* __restrict__ Y,
    int64_t outer, int64_t reduce_size, int64_t inner)
{
    // Represent input as a 3D tensor (outer, reduce_size, inner) contiguous
    auto mX = make_tensor(
        make_gmem_ptr(X),
        make_shape(outer, reduce_size, inner),
        make_stride(reduce_size * inner, inner, Int<1>{})
    );

    // Output as a 2D tensor (outer, inner)
    auto mY = make_tensor(
        make_gmem_ptr(Y),
        make_shape(outer, inner),
        make_stride(inner, Int<1>{})
    );

    int64_t o = blockIdx.x;
    int64_t i = (int64_t)blockIdx.y * blockDim.x + threadIdx.x;

    if (o >= outer || i >= inner) return;

    T acc = mX(o, 0, i);
    #pragma unroll 4
    for (int64_t k = 1; k < reduce_size; ++k) {
        T v = mX(o, k, i);
        acc = v < acc ? v : acc;
    }

    mY(o, i) = acc;
}

torch::Tensor min_reduce_dim_forward(torch::Tensor x, int64_t dim) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
